"""Intrinsic-color, 32 x 32 pixel props used by NPC frames and portraits.

Allocation lives in the design specification; this module only owns artwork.
All silhouettes use integer orthogonal paths and a dark one-pixel outline.
"""
from __future__ import annotations


def _p(color: str, path: str) -> str:
    return f'<path fill="{color}" d="{path}"/>'


def _r(color: str, x: int, y: int, width: int, height: int) -> str:
    return f'<rect fill="{color}" x="{x}" y="{y}" width="{width}" height="{height}"/>'


INK = '#20202c'
WOOD = '#92613c'
GOLD = '#ddb35f'
LIGHT = '#f8e6b1'
STEEL = '#98adba'
WHITE = '#ebf2e7'
GREEN = '#5d9460'
PINK = '#de8ca7'
BLUE = '#638bae'


def _art(outline: str, *layers: tuple[str, str]) -> str:
    """A hand-drawn stepped silhouette followed by opaque color regions."""
    return _p(INK, outline) + ''.join(_p(color, shape) for color, shape in layers)

